document.addEventListener("DOMContentLoaded",function(){const e=new Date("2027-12-04T00:00:00-06:00"),t=document.getElementById("countdown");if(!t)return;t.innerHTML="";["Days","Hours","Minutes","Seconds"].forEach(e=>t.appendChild(function(e){const t=document.createElement("div");t.className="countdown-item";const n=document.createElement("span");n.className="countdown-number",n.textContent="0";const o=document.createElement("span");return o.className="countdown-label",o.textContent=e,t.appendChild(n),t.appendChild(o),t}(e)));const n=t.querySelectorAll(".countdown-number");function o(){const o=new Date,a=e-o;if(a<=0)return t.textContent="The big day is here!",void clearInterval(c);[Math.floor(a/864e5),Math.floor(a/36e5%24),Math.floor(a/6e4%60),Math.floor(a/1e3%60)].forEach((e,t)=>{n[t]&&(n[t].textContent=e)})}const c=setInterval(o,1e3);o()});